 JSONObject call(String method,String path,JSONObject data,boolean auth)throws Exception {HttpsURLConnection c=(HttpsURLConnection)new URL(BASE+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestMethod(method);if(auth)c.setRequestProperty("Authorization","Bearer "+store.get("access_token"));try{if(data!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(data.toString().getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();InputStream source=status>=200&&status<300?c.getInputStream():c.getErrorStream();if(source==null)throw new IOException("Server unavailable");ByteArrayOutputStream out=new ByteArrayOutputStream();try(source){byte[] b=new byte[4096];int n;while((n=source.read(b))!=-1){if(out.size()+n>2000000)throw new IOException("Response too large");out.write(b,0,n);}}JSONObject result=new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));if(status<200||status>=300){if(status==401&&auth)store.put("access_token","");if(status==401&&!auth&&path.endsWith("/exchange"))store.put("pending_pair","");throw new IOException(result.optString("detail","Request failed"));}return result;}finally{c.disconnect();}}
 String errorMessage(Exception error){String message=error.getMessage();if(error instanceof java.net.SocketTimeoutException||error instanceof java.net.UnknownHostException||error instanceof java.net.ConnectException||error instanceof javax.net.ssl.SSLException)return "We couldn't reach Loop Secure. Check this phone's internet connection and try again.";if(message==null||message.trim().isEmpty())return "The request could not be completed. Please try again.";return message;}
 void fail(Exception e){ui(()->{busy=false;notice=errorMessage(e);try{if(store.get("access_token").isEmpty())login();else if(overview!=null)render();}catch(Exception ignored){}new MaterialAlertDialogBuilder(this).setTitle("Request not completed").setMessage(notice).setPositiveButton("Close",null).show();});}
 void connect(){
  try{String saved=store.get("pending_pair");if(!saved.isEmpty()){JSONObject pair=new JSONObject(saved);if(pair.optLong("expires")>System.currentTimeMillis()/1000){if(busy)startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(pair.getString("approval_url"))));else resumePair(pair,true);return;}store.put("pending_pair","");}}catch(Exception ignored){}
  if(busy)return;busy=true;notice="Opening owner sign-in. Approve this phone on the website, then return here.";login();
  worker.execute(()->{try{JSONObject pair=call("POST","/api/admin-app/connect",new JSONObject().put("name",Build.MODEL),false);store.put("pending_pair",pair.toString());ui(()->{busy=false;resumePair(pair,true);});}catch(Exception e){fail(e);}});
 }
 void resumePair(JSONObject pair,boolean openBrowser){
  if(busy)return;busy=true;notice="Waiting for approval. Match code "+pair.optString("ticket").substring(0,8).toUpperCase(Locale.ROOT)+" on the website, then choose Approve this app.";login();
  if(openBrowser)startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(pair.optString("approval_url"))));
  worker.execute(()->{try{for(int i=0;i<180&&!destroyed;i++){JSONObject result=call("POST","/api/admin-app/exchange",new JSONObject().put("ticket",pair.getString("ticket")).put("device_secret",pair.getString("device_secret")),false);if(result.optString("status").equals("connected")){store.put("access_token",result.getString("access_token"));store.put("pending_pair","");AdminPaymentAlerts.schedule(this);ui(()->{busy=false;notice="";refresh();});return;}Thread.sleep(3000);}store.put("pending_pair","");throw new IOException("This connection request expired. Sign in again to get a new code.");}catch(Exception e){fail(e);}});
 }
