 void clients(){button(content,"+  Enroll customer",this::enroll);gap(content,12);EditText search=input("Search name, phone or reference");customerSearch=search;search.setText(customerQuery);search.setInputType(android.text.InputType.TYPE_CLASS_TEXT);content.addView(search);gap(content,18);LinearLayout list=column();content.addView(list);Runnable fill=()->{list.removeAllViews();LinearLayout old=content;content=list;String q=search.getText().toString().toLowerCase(Locale.ROOT);int found=0;for(int i=0;i<devices().length();i++){JSONObject d=devices().optJSONObject(i);if((d.optString("name")+d.optString("phone")+d.optString("reference")).toLowerCase(Locale.ROOT).contains(q)){deviceCard(d);found++;}}if(found==0)empty(q.isEmpty()?"No customers yet.":"No matching customers.",q.isEmpty()?"Enroll a customer using their name and phone number.":"Try another name, phone number or account reference.");content=old;};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){customerQuery=s.toString();fill.run();}public void afterTextChanged(android.text.Editable e){}});fill.run();}
 void command(JSONObject d,String action){if(busy)return;busy=true;worker.execute(()->{try{call("POST","/api/admin/devices/"+d.getString("id")+"/control",new JSONObject().put("action",action).put("request_key",UUID.randomUUID().toString()),true);ui(()->{busy=false;notice="Command queued. The phone has not confirmed it yet.";refresh();});}catch(Exception e){fail(e);}});}
 void message(JSONObject d){EditText input=input("Message to customer");LinearLayout form=form();form.addView(input);new MaterialAlertDialogBuilder(this).setTitle("Message customer").setView(form).setPositiveButton("Send",(a,b)->worker.execute(()->{try{call("POST","/api/admin/messages",new JSONObject().put("request_key",UUID.randomUUID().toString()).put("title","Loop Secure support").put("message",input.getText().toString()).put("device_ids",new JSONArray().put(d.getString("id"))).put("all_active",false),true);ui(()->{notice="Message queued for customer delivery.";render();});}catch(Exception e){fail(e);}})).setNegativeButton("Cancel",null).show();}
 void payments(){JSONArray claims=overview.optJSONArray("claims");label(content,"Check settled funds in your bank before approving a claim.",13,muted);gap(content,10);if(claims==null||claims.length()==0){empty("No payment claims yet.","Customer EFT claims appear here when they are submitted.");return;}for(int i=0;i<claims.length();i++){JSONObject cl=claims.optJSONObject(i);LinearLayout body=card();LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);LinearLayout identity=column();TextView name=text(cl.optString("name"),17,ink,true);identity.addView(name);gap(identity,5);identity.addView(text(cl.optString("reference"),11,muted,false));row.addView(identity,new LinearLayout.LayoutParams(0,-2,1));TextView amount=text("R"+cl.optInt("amount"),25,ink,false);row.addView(amount);body.addView(row);gap(body,14);line(body,rule,1);gap(body,12);String state=cl.optString("state");int stateColor=state.equals("rejected")?danger:state.equals("pending")?amber:0xff17866a;TextView status=text(state.equals("pending")?"Awaiting review":state.equals("approved")?"Approved":"Rejected",11,stateColor,true);status.setPadding(dp(9),dp(6),dp(9),dp(6));status.setBackground(panel(state.equals("pending")?0xfffff8e9:state.equals("approved")?0xffedf8f3:0xfffff0f1,9));body.addView(status,new LinearLayout.LayoutParams(-2,-2));gap(body,12);label(body,"EFT reference: "+cl.optString("bank_reference","Not supplied"),12,ink);long submitted=cl.optLong("submitted");if(submitted>0)label(body,"Submitted "+dateTime(submitted),10,muted);if(state.equals("pending"))button(body,"Review payment",()->review(cl));}}
 void review(JSONObject claim){EditText reference=input("Settled bank transaction reference");LinearLayout form=form();form.addView(reference);new MaterialAlertDialogBuilder(this).setTitle("Review EFT settlement").setMessage("Account: "+claim.optString("reference")+"\nSubmitted EFT reference: "+claim.optString("bank_reference","Not supplied")+"\n\nCheck your bank account before approving. A payment claim does not confirm that the funds have arrived.").setView(form).setPositiveButton("Approve settled EFT",(a,b)->reviewCall(claim,"approve",reference.getText().toString())).setNeutralButton("Reject claim",(a,b)->reviewCall(claim,"reject","")).setNegativeButton("Cancel",null).show();}
 void reviewCall(JSONObject claim,String decision,String receipt){worker.execute(()->{try{call("POST","/api/admin/claims/"+claim.getString("id")+"/review",new JSONObject().put("decision",decision).put("reason",decision.equals("approve")?"Administrator confirmed settled bank funds":"Administrator could not verify settlement").put("receipt_reference",receipt),true);ui(()->{notice="Payment review saved. Waiting for the phone to receive the update.";refresh();});}catch(Exception e){fail(e);}});}
 void enroll(){LinearLayout form=form();EditText name=input("Customer name"),phone=input("Phone number");name.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_WORDS);phone.setInputType(android.text.InputType.TYPE_CLASS_PHONE);form.addView(name);form.addView(phone);new MaterialAlertDialogBuilder(this).setTitle("Enroll customer").setMessage("Confirm the customer has agreed to device management. Their plan and supported policies are set automatically.").setView(form).setPositiveButton("Generate QR",(a,b)->worker.execute(()->{try{JSONObject e=call("POST","/api/admin/enrollments",new JSONObject().put("name",name.getText().toString()).put("phone",phone.getText().toString()),true);JSONObject installer=call("GET","/api/admin/provisioning/apk",null,true);JSONObject payload=new JSONObject().put("enrollment_token",e.getString("enrollment_token")).put("apk_url",installer.getString("apk_url")).put("apk_sha256",installer.getString("apk_sha256"));String svg=rawQr(payload);ui(()->{android.webkit.WebView qr=new android.webkit.WebView(this);qr.setMinimumHeight(dp(360));qr.getSettings().setJavaScriptEnabled(false);qr.getSettings().setAllowFileAccess(false);qr.getSettings().setBlockNetworkLoads(true);qr.loadDataWithBaseURL(null,svg,"image/svg+xml","UTF-8",null);new MaterialAlertDialogBuilder(this).setTitle("Scan during Android setup").setView(qr).setPositiveButton("Close",(d,n)->refresh()).show();});}catch(Exception ex){fail(ex);}})).setNegativeButton("Cancel",null).show();}
 String rawQr(JSONObject data)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new URL(BASE+"/api/admin/provisioning/qr").openConnection();c.setRequestMethod("POST");c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setDoOutput(true);c.setRequestProperty("Authorization","Bearer "+store.get("access_token"));c.setRequestProperty("Content-Type","application/json");try{try(OutputStream out=c.getOutputStream()){out.write(data.toString().getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()!=200)throw new IOException("Could not generate enrollment QR");try(InputStream input=c.getInputStream()){byte[] bytes=za.co.bacy.ui.BoundedInput.read(input,300000);return new String(bytes,StandardCharsets.UTF_8);}}finally{c.disconnect();}}
 void settings(){LinearLayout body=card();LinearLayout title=new LinearLayout(this);title.setGravity(Gravity.CENTER_VERTICAL);title.addView(new za.co.bacy.ui.InstrumentIcon(this,"shield",blue),new LinearLayout.LayoutParams(dp(23),dp(23)));TextView titleText=text("Owner access",21,ink,false);titleText.setPadding(dp(10),0,0,0);title.addView(titleText);body.addView(title);gap(body,16);label(body,"This phone stays connected for up to seven days. Manage its access from the administrator website.",14,muted);gap(body,6);button(body,"Refresh records",this::refresh);action(body,"Open administrator website",false,()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(SITE))));gap(body,7);line(body,rule,1);gap(body,7);action(body,"Disconnect this app",false,()->worker.execute(()->{try{call("POST","/api/admin/mobile/disconnect",new JSONObject(),true);store.put("access_token","");AdminPaymentAlerts.cancel(this);ui(this::login);}catch(Exception e){fail(e);}}));gap(content,10);label(content,"Support",19,ink);label(content,"basanisilinda@gmail.com",14,blue);}
